class Solution {
public:
    int beautifulSubsets(std::vector<int>& nums, int k) {
        std::sort(nums.begin(), nums.end());
        std::unordered_map<int, int> count;
        int ans = 0;
        auto backtrack = [&](auto& self, int i) -> void {
            if (i == (int)nums.size()) {
                ans++;
                return;
            }
            self(self, i + 1);
            if (count[nums[i] - k] == 0) {
                count[nums[i]]++;
                self(self, i + 1);
                count[nums[i]]--;
            }
        };
        backtrack(backtrack, 0);
        return ans - 1;
    }
};

class Solution {
    private int ans = 0;
    public int beautifulSubsets(int[] nums, int k) {
        java.util.Arrays.sort(nums);
        java.util.Map<Integer, Integer> count = new java.util.HashMap<>();
        backtrack(0, nums, k, count);
        return ans - 1;
    }
    private void backtrack(int i, int[] nums, int k, java.util.Map<Integer, Integer> count) {
        if (i == nums.length) {
            ans++;
            return;
        }
        backtrack(i + 1, nums, k, count);
        if (count.getOrDefault(nums[i] - k, 0) == 0) {
            count.put(nums[i], count.getOrDefault(nums[i], 0) + 1);
            backtrack(i + 1, nums, k, count);
            count.put(nums[i], count.get(nums[i]) - 1);
        }
    }
}

var beautifulSubsets = function(nums, k) {
    nums.sort((a, b) => a - b);
    const count = new Map();
    let ans = 0;
    function backtrack(i) {
        if (i === nums.length) {
            ans++;
            return;
        }
        backtrack(i + 1);
        if ((count.get(nums[i] - k) || 0) === 0) {
            count.set(nums[i], (count.get(nums[i]) || 0) + 1);
            backtrack(i + 1);
            count.set(nums[i], count.get(nums[i]) - 1);
        }
    }
    backtrack(0);
    return ans - 1;
};
